object UserRoleTable : Table("user_roles") {
    val user = reference("user_id", Users)
    val role = reference("role_id", Roles)
    override val primaryKey = PrimaryKey(user, role)
}

class UserEntity(id: EntityID<Int>) : IntEntity(id) {
    companion object : IntEntityClass<UserEntity>(Users)
    var roles by RoleEntity via UserRoleTable
}

UserEntity.all().with(UserEntity::roles)   // eager load, no N+1
